argv:
$ErrorActionPreference='Stop';
$repo='E:\WebAIBridge';
$expectedHead='e8033f2e42bd335c10a397eb3d2cb62c8bb837a9';
$files=@('app/scripts/operator-lifecycle-r40.ps1','app/scripts/pause-all-r40.cmd','app/scripts/pause-browser-r40.cmd','app/scripts/resume-attach-r40.cmd','app/scripts/resume-managed-r40.cmd');
$git=(Get-Command git.exe -CommandType Application -ErrorAction Stop | Select-Object -First 1).Path;
$head=((@(& $git -C $repo rev-parse HEAD))-join '').Trim();
if($head -ne $expectedHead){throw ('Unexpected HEAD: '+$head)}
$status=@(& $git -C $repo status --short);
$expected=@($files|ForEach-Object{' M '+$_});
if((($status|Sort-Object)-join [Environment]::NewLine) -ne (($expected|Sort-Object)-join [Environment]::NewLine)){throw ('Dirty set changed: '+($status -join '; '))}
$latest=Get-ChildItem (Join-Path $repo 'app\data\backups') -Directory -Filter 'r42-dirty-quarantine-*' | Sort-Object LastWriteTimeUtc -Descending | Select-Object -First 1;
if($null -eq $latest){throw 'Quarantine backup not found'}
$qmanifest=Join-Path $latest.FullName 'manifest.json';
if(!(Test-Path -LiteralPath $qmanifest)){throw 'Quarantine manifest missing'}
$restored=@();
foreach($f in $files){
  $blob=((@(& $git -C $repo rev-parse ('HEAD:'+$f)))-join '').Trim();
  if($blob -notmatch '^[0-9a-f]{40}$'){throw ('Invalid HEAD blob for '+$f)}
  $dest=Join-Path $repo $f;
  $psi=New-Object System.Diagnostics.ProcessStartInfo;
  $psi.FileName=$git;
  $psi.Arguments=('-C '+$repo+' cat-file blob '+$blob);
  $psi.UseShellExecute=$false;
  $psi.RedirectStandardOutput=$true;
  $psi.RedirectStandardError=$true;
  $p=New-Object System.Diagnostics.Process;
  $p.StartInfo=$psi;
  if(-not $p.Start()){throw ('Failed to start git cat-file for '+$f)}
  $fs=[IO.File]::Open($dest,[IO.FileMode]::Create,[IO.FileAccess]::Write,[IO.FileShare]::None);
  try{$p.StandardOutput.BaseStream.CopyTo($fs)}finally{$fs.Dispose()}
  $err=$p.StandardError.ReadToEnd();$p.WaitForExit();
  if($p.ExitCode -ne 0){throw ('git cat-file failed for '+$f+': '+$err)}
  $workBlob=((@(& $git -C $repo hash-object --path=$f $dest))-join '').Trim();
  if($workBlob -ne $blob){throw ('Restored blob mismatch for '+$f+' expected '+$blob+' got '+$workBlob)}
  $restored += [pscustomobject]@{file=$f;blob=$blob;rawSha256=(Get-FileHash -LiteralPath $dest -Algorithm SHA256).Hash.ToLowerInvariant()}
}
$after=@(& $git -C $repo status --short);
if($after.Count -ne 0){throw ('Worktree still dirty after exact blob restore: '+($after -join '; '))}
[pscustomobject]@{status='EXACT_FIVE_BLOBS_RESTORED';head=$head;quarantine=$latest.FullName;files=$restored;dirtyAfter=0}|ConvertTo-Json -Depth 6 -Compress
